constants.pp_no_notation:
∀ {M : LifoBackpressure.Statements.NetworkModel} {Ω : Type} [inst : MeasurableSpace Ω] {μ : MeasureTheory.Measure Ω}
  [inst_1 : MeasureTheory.IsProbabilityMeasure μ] {proc : M.MarkovProcess Ω μ} {pol : M.Policy proc} {j : Fin M.r}
  {ι : Type} (L : LifoBackpressure.Statements.LifoQueueRealization pol j ι) (γstar_j D K V : Real) (ω : Ω)
  (k : Subtype fun k => Membership.mem (L.windowDepartingSet γstar_j D K V ω) k),
  Membership.mem (LifoBackpressure.Statements.LifoQueueRealization.enlargedBufferSlots γstar_j D K V M.δmax)
    (L.slot ω ↑k)

∀ {M : LifoBackpressure.Statements.NetworkModel} {Ω : Type} [inst : MeasurableSpace Ω] {μ : MeasureTheory.Measure Ω}
  [inst_1 : MeasureTheory.IsProbabilityMeasure μ] {proc : M.MarkovProcess Ω μ} {pol : M.Policy proc} {j : Fin M.r}
  {ι : Type} (L : LifoBackpressure.Statements.LifoQueueRealization pol j ι) (γstar_j D K V : Real) (ω : Ω)
  (k : Subtype fun k => Membership.mem (L.windowDepartingSet γstar_j D K V ω) k),
  LE.le (↑(L.arrival ω ↑k)) (L.depart ω ↑k)

∀ {M : LifoBackpressure.Statements.NetworkModel} {Ω : Type} [inst : MeasurableSpace Ω] {μ : MeasureTheory.Measure Ω}
  [inst_1 : MeasureTheory.IsProbabilityMeasure μ] {proc : M.MarkovProcess Ω μ} {pol : M.Policy proc} {j : Fin M.r}
  {ι : Type} (L : LifoBackpressure.Statements.LifoQueueRealization pol j ι) (γstar_j D K V : Real) (ω : Ω) (t : Nat),
  (Set.preimage Subtype.val (Set.ofPred fun k => LT.lt (L.arrival ω k) t)).Finite

∀ {M : LifoBackpressure.Statements.NetworkModel} {Ω : Type} [inst : MeasurableSpace Ω] {μ : MeasureTheory.Measure Ω}
  [inst_1 : MeasureTheory.IsProbabilityMeasure μ] {proc : M.MarkovProcess Ω μ} {pol : M.Policy proc} {j : Fin M.r}
  {ι : Type} (L : LifoBackpressure.Statements.LifoQueueRealization pol j ι) (γstar_j D K V : Real) (ω : Ω) (t : Nat),
  Set.Finite fun k => And (LT.lt (L.arrival ω k) t) (Membership.mem (L.windowDepartingSet γstar_j D K V ω) k)
